class Parser(object):
    '''Encapsulate a format string that may be used to parse other strings.
    '''
    def __init__(self, format, extra_types=None, case_sensitive=False):
        # Validate brace matching before anything else
        self._validate_braces(format)

        # a mapping of a name as in {hello.world} to a regex-group compatible
        # name, like hello__world Its used to prevent the transformation of
        # name-to-group and group to name to fail subtly, such as in:
        # hello_.world-> hello___world->hello._world
        self._group_to_name_map = {}
        # also store the original field name to group name mapping to allow
        # multiple instances of a name in the format string
        self._name_to_group_map = {}
        # and to sanity check the repeated instances store away the first
        # field type specification for the named field
        self._name_types = {}

        self._format = format
        if extra_types is None:
            extra_types = {}
        self._extra_types = extra_types
        if case_sensitive:
            self._re_flags = re.DOTALL
        else:
            self._re_flags = re.IGNORECASE | re.DOTALL
        self._fixed_fields = []
        self._named_fields = []
        self._group_index = 0
        self._type_conversions = {}
        self._expression = self._generate_expression()
        self.__search_re = None
        self.__match_re = None

        log.debug('format %r -> %r', format, self._expression)

    def _validate_braces(self, format):
        """Validate that all braces are properly matched and enclosed."""
        i = 0
        while i < len(format):
            if format[i] == '{':
                # Found an opening brace - must find closing brace
                j = i + 1
                depth = 1
                while j < len(format) and depth > 0:
                    if format[j] == '{':
                        depth += 1
                    elif format[j] == '}':
                        depth -= 1
                    j += 1
                if depth != 0:
                    raise ValueError("Format string has unmatched opening brace at position %d" % i)
                # Check that the content between braces is valid (not empty or just whitespace with no type)
                content = format[i+1:j-1].strip()
                if not content and '}' not in format[i:i+2]:
                    # Empty field {} is valid, but check for unclosed
                    pass
            elif format[i] == '}':
                # Found a closing brace without matching opening
                raise ValueError("Format string has unmatched closing brace at position %d" % i)
            i += 1

